import {createCMS} from 'alinea/next'

export const cms = createCMS({
  // schema and workspaces ...
  baseUrl: {
    development: 'http://localhost:3000',
    production: 'https://example.com'
  },
  handlerUrl: '/api/cms',
  preview: true
})

import {cms} from '@/cms'
import type {PropsWithChildren} from 'react'

export default function RootLayout({children}: PropsWithChildren) {
  return (
    <html lang="en">
      <body>
        {children}
        <cms.previews widget />
      </body>
    </html>
  )
}

import {Config, Field} from 'alinea'

export const Settings = Config.document('Settings', {
  preview: false,
  fields: {
    siteName: Field.text('Site name')
  }
})

import {Config, Field} from 'alinea'

export const Snippet = Config.document('Snippet', {
  entryUrl: ({path}) => `/preview/snippets/${path}`,
  fields: {
    body: Field.richText('Body')
  }
})

import {cms} from '@/cms'
import {Snippet} from '@/schema/Snippet'
import type {Metadata} from 'next'
import {notFound} from 'next/navigation'

interface SnippetPreviewProps {
  params: Promise<{slug: string}>
}

export const metadata: Metadata = {robots: {index: false}}

export default async function SnippetPreview({params}: SnippetPreviewProps) {
  const {slug} = await params
  const snippet = await cms.first({
    type: Snippet,
    url: `/preview/snippets/${slug}`
  })
  if (!snippet) notFound()
  return <main>{/* render the snippet like it appears on your pages */}</main>
}

import {Config, Field} from 'alinea'

export const Announcement = Config.document('Announcement', {
  preview({entry}) {
    const {message} = entry.data as {message?: string}
    return <div style={{padding: 16}}>{message || entry.title}</div>
  },
  fields: {
    message: Field.text('Message')
  }
})
